/* Interactive 3D viewer of infrastructures glTF representations generated by
 * RacksDB. This module imports three.js, it is meant to be loaded dynamically to keep
 * three.js out of the main bundle. */

import {
  AmbientLight,
  Box3,
  Color,
  DirectionalLight,
  HemisphereLight,
  MathUtils,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  PerspectiveCamera,
  Raycaster,
  Scene,
  Vector2,
  Vector3,
  WebGLRenderer,
  type Material
} from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { GLTFLoader, type GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js'

export const EQUIPMENT_CATEGORIES = new Set(['node', 'storage', 'network', 'misc'])

const CAMERA_FOV = 45
const HIGHLIGHT_INTENSITY = 0.4
// Turntable camera rotation speed, in radians per second
export const TURNTABLE_SPEED = 0.25
// Duration of eased camera transitions, in seconds
export const TRANSITION_DURATION = 0.9

export type CameraMode = 'free' | 'turntable'

export interface HoveredEquipment {
  name: string
  category: string
  type: string
  rack: string
}

export interface Focus {
  center: Vector3
  size: Vector3
  radius: number
}

/* Return the closest ancestor of object (including itself) representing an
 * equipment, or null if not found. */
export function findEquipment(object: Object3D | null): Object3D | null {
  let current = object
  while (current) {
    if (EQUIPMENT_CATEGORIES.has(current.userData?.category)) {
      return current
    }
    current = current.parent
  }
  return null
}

/* Return the bounding box center, size and radius of all racks in root, or of the
 * whole root if it does not contain racks. */
export function computeFocus(root: Object3D): Focus {
  root.updateMatrixWorld(true)
  const box = new Box3()
  root.traverse((object) => {
    if (object.userData?.category === 'rack') {
      box.union(new Box3().setFromObject(object))
    }
  })
  if (box.isEmpty()) {
    box.setFromObject(root)
  }
  const center = box.getCenter(new Vector3())
  const size = box.getSize(new Vector3())
  return { center, size, radius: Math.max(size.length() / 2, 0.5) }
}

/* Return camera position to view the whole focus area from above, with the given
 * vertical field of view in degrees. The azimuth is the angle in radians of the
 * camera around the vertical axis of the focus area, 0 being the front (+Z) of the
 * area. */
export function cameraPosition(
  focus: Focus,
  fov: number = CAMERA_FOV,
  azimuth: number = 0
): Vector3 {
  const distance = (focus.radius / Math.sin(MathUtils.degToRad(fov) / 2)) * 1.1
  const elevation = MathUtils.degToRad(30)
  const horizontal = distance * Math.cos(elevation)
  return new Vector3(
    focus.center.x + horizontal * Math.sin(azimuth),
    focus.center.y + distance * Math.sin(elevation),
    focus.center.z + horizontal * Math.cos(azimuth)
  )
}

/* Return the azimuth in radians of the given position around the vertical axis of
 * the focus area, 0 being the front (+Z) of the area. */
export function cameraAzimuth(position: Vector3, focus: Focus): number {
  return Math.atan2(position.x - focus.center.x, position.z - focus.center.z)
}

export function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2
}

/* Eased transition of camera position and target. */
export interface CameraTransition {
  fromPosition: Vector3
  toPosition: Vector3
  fromTarget: Vector3
  toTarget: Vector3
  elapsed: number
  duration: number
}

export function createTransition(
  fromPosition: Vector3,
  toPosition: Vector3,
  fromTarget: Vector3,
  toTarget: Vector3,
  duration: number = TRANSITION_DURATION
): CameraTransition {
  return {
    fromPosition: fromPosition.clone(),
    toPosition: toPosition.clone(),
    fromTarget: fromTarget.clone(),
    toTarget: toTarget.clone(),
    elapsed: 0,
    duration
  }
}

/* Advance transition by delta seconds and write the resulting camera position and
 * target in the given vectors. Return true when the transition is finished. */
export function stepTransition(
  transition: CameraTransition,
  delta: number,
  position: Vector3,
  target: Vector3
): boolean {
  transition.elapsed += delta
  const progress =
    transition.duration > 0 ? Math.min(transition.elapsed / transition.duration, 1) : 1
  const eased = easeInOutCubic(progress)
  position.lerpVectors(transition.fromPosition, transition.toPosition, eased)
  target.lerpVectors(transition.fromTarget, transition.toTarget, eased)
  return progress >= 1
}

function prefersReducedMotion(): boolean {
  return (
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

/* Return the name of the glTF node of the given object. Three.js sanitizes object
 * names, the original name is retrieved from the glTF document when possible. */
export function originalName(gltf: GLTF, object: Object3D): string {
  const index = gltf.parser.associations.get(object)?.nodes
  if (index !== undefined) {
    const name = gltf.parser.json.nodes?.[index]?.name
    if (name) {
      return name
    }
  }
  return object.name
}

export function parseGlb(data: ArrayBuffer): Promise<GLTF> {
  return new Promise((resolve, reject) => {
    new GLTFLoader().parse(data, '', resolve, reject)
  })
}

export class InfrastructureViewer {
  private renderer: WebGLRenderer
  private scene = new Scene()
  private camera = new PerspectiveCamera(CAMERA_FOV, 1, 0.05, 1000)
  private controls: OrbitControls
  private focus: Focus
  private raycaster = new Raycaster()
  private pointer: Vector2 | null = null
  private hovered: Object3D | null = null
  // Original materials of highlighted meshes
  private highlighted = new Map<Mesh, Material>()
  private resizeObserver: ResizeObserver | null = null
  private animationFrame = 0
  private lastFrame = 0
  private mode: CameraMode = 'free'
  // Current eased camera transition, controls are disabled while it is running.
  private transition: CameraTransition | null = null
  // Point looked by camera when controls are disabled
  private lookTarget = new Vector3()
  // Turntable camera azimuth and time since turntable rotation started
  private turntableAngle = 0
  private turntableTime = 0

  constructor(
    private container: HTMLElement,
    private gltf: GLTF,
    private onHover: (equipment: HoveredEquipment | null) => void,
    private onModeChange: (mode: CameraMode) => void = () => {}
  ) {
    this.renderer = new WebGLRenderer({ antialias: true })
    this.renderer.setPixelRatio(window.devicePixelRatio)
    const canvas = this.renderer.domElement
    canvas.classList.add('block', 'h-full', 'w-full')
    container.appendChild(canvas)

    this.scene.background = new Color(0xf3f4f6)
    this.scene.add(new AmbientLight(0xffffff, 0.8))
    this.scene.add(new HemisphereLight(0xf5f7ff, 0x8a9099, 0.5))
    const key = new DirectionalLight(0xffffff, 0.8)
    key.position.set(5, 14, 8)
    this.scene.add(key)
    const fill = new DirectionalLight(0xffffff, 0.35)
    fill.position.set(-6, 9, -4)
    this.scene.add(fill)
    this.scene.add(gltf.scene)

    const anisotropy = this.renderer.capabilities.getMaxAnisotropy()
    gltf.scene.traverse((object) => {
      const mesh = object as Mesh
      if (mesh.isMesh) {
        for (const material of [mesh.material].flat()) {
          const map = (material as MeshStandardMaterial).map
          if (map) map.anisotropy = anisotropy
        }
      }
    })

    // These listeners are registered before the controls, so they are called
    // first and re-enable the controls in time for the controls to handle the same
    // events.
    canvas.addEventListener('pointerdown', this.onPointerDown)
    canvas.addEventListener('pointermove', this.onPointerMove)
    canvas.addEventListener('pointerleave', this.onPointerLeave)

    this.controls = new OrbitControls(this.camera, canvas)
    this.controls.enableDamping = true
    this.controls.screenSpacePanning = true
    // Keep camera above the floor
    this.controls.maxPolarAngle = Math.PI / 2 - 0.05
    this.focus = computeFocus(gltf.scene)
    this.controls.maxDistance = this.focus.radius * 10
    this.camera.position.copy(cameraPosition(this.focus))
    this.controls.target.copy(this.focus.center)
    this.controls.update()

    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.resize())
      this.resizeObserver.observe(container)
    }
    this.resize()
    this.animate()
  }

  /* Move camera with an eased transition to its initial position, in free mode. */
  resetCamera() {
    this.setModeValue('free')
    this.startTransition(cameraPosition(this.focus), this.focus.center)
  }

  /* Switch camera mode. In turntable mode, the camera moves with an eased
   * transition to the orbit around the racks and rotates. In free mode, the camera
   * stops where it is and it is controlled by the user. */
  setMode(mode: CameraMode) {
    if (mode === 'turntable') {
      if (this.mode === 'turntable') return
      this.setModeValue('turntable')
      this.turntableAngle = cameraAzimuth(this.camera.position, this.focus)
      this.turntableTime = 0
      this.startTransition(
        cameraPosition(this.focus, CAMERA_FOV, this.turntableAngle),
        this.focus.center
      )
      return
    }
    if (this.mode === 'free' && !this.transition) return
    this.transition = null
    this.setModeValue('free')
    this.enableControls(this.lookTarget)
  }

  resize() {
    const { clientWidth: width, clientHeight: height } = this.container
    if (!width || !height) return
    this.camera.aspect = width / height
    this.camera.updateProjectionMatrix()
    this.renderer.setSize(width, height, false)
  }

  dispose() {
    cancelAnimationFrame(this.animationFrame)
    this.resizeObserver?.disconnect()
    const canvas = this.renderer.domElement
    canvas.removeEventListener('pointerdown', this.onPointerDown)
    canvas.removeEventListener('pointermove', this.onPointerMove)
    canvas.removeEventListener('pointerleave', this.onPointerLeave)
    this.setHovered(null)
    this.controls.dispose()
    this.scene.traverse((object) => {
      const mesh = object as Mesh
      if (mesh.geometry) mesh.geometry.dispose()
      if (mesh.material) {
        for (const material of [mesh.material].flat()) {
          ;(material as MeshStandardMaterial).map?.dispose()
          material.dispose()
        }
      }
    })
    this.renderer.dispose()
    canvas.remove()
  }

  private setModeValue(mode: CameraMode) {
    if (mode === this.mode) return
    this.mode = mode
    this.onModeChange(mode)
  }

  /* Start eased transition of camera from its current position and target to the
   * given position and target, with controls disabled. */
  private startTransition(position: Vector3, target: Vector3) {
    // When a transition is already running, the controls are already disabled and
    // the camera looks at lookTarget.
    const fromTarget = this.controls.enabled ? this.controls.target : this.lookTarget
    this.transition = createTransition(
      this.camera.position,
      position,
      fromTarget,
      target,
      prefersReducedMotion() ? 0 : TRANSITION_DURATION
    )
    this.lookTarget.copy(fromTarget)
    this.controls.enabled = false
  }

  /* Give camera control back to the user, looking at the given target. */
  private enableControls(target: Vector3) {
    if (this.controls.enabled) return
    // Discard controls inertia remaining from user moves before controls were
    // disabled: an update without damping consumes it, then camera is restored.
    const position = this.camera.position.clone()
    this.controls.enableDamping = false
    this.controls.update()
    this.controls.enableDamping = true
    this.camera.position.copy(position)
    this.controls.target.copy(target)
    this.controls.enabled = true
    this.controls.update()
  }

  private animate = () => {
    this.animationFrame = requestAnimationFrame(this.animate)
    const now = performance.now()
    // Limit delta to avoid jumps when the page was in background.
    const delta = this.lastFrame ? Math.min((now - this.lastFrame) / 1000, 0.1) : 0
    this.lastFrame = now
    if (this.pointer) {
      this.pick(this.pointer)
      this.pointer = null
    }
    if (this.transition) {
      const finished = stepTransition(this.transition, delta, this.camera.position, this.lookTarget)
      this.camera.lookAt(this.lookTarget)
      if (finished) {
        this.transition = null
        if (this.mode === 'free') this.enableControls(this.lookTarget)
      }
    } else if (this.mode === 'turntable') {
      // Ease in rotation speed during the first second.
      this.turntableTime += delta
      this.turntableAngle +=
        TURNTABLE_SPEED * easeInOutCubic(Math.min(this.turntableTime, 1)) * delta
      this.camera.position.copy(cameraPosition(this.focus, CAMERA_FOV, this.turntableAngle))
      this.lookTarget.copy(this.focus.center)
      this.camera.lookAt(this.lookTarget)
    } else {
      this.controls.update()
    }
    this.renderer.render(this.scene, this.camera)
  }

  /* Stop turntable and transitions as soon as the user clicks in the scene. */
  private onPointerDown = () => {
    this.setMode('free')
  }

  private onPointerMove = (event: PointerEvent) => {
    const rect = this.renderer.domElement.getBoundingClientRect()
    this.pointer = new Vector2(
      ((event.clientX - rect.left) / rect.width) * 2 - 1,
      -((event.clientY - rect.top) / rect.height) * 2 + 1
    )
  }

  private onPointerLeave = () => {
    this.pointer = null
    this.setHovered(null)
  }

  private pick(pointer: Vector2) {
    this.raycaster.setFromCamera(pointer, this.camera)
    // Only consider meshes, equipment edges are lines with large picking threshold.
    const hit = this.raycaster
      .intersectObject(this.gltf.scene, true)
      .find((intersection) => (intersection.object as Mesh).isMesh)
    this.setHovered(hit ? findEquipment(hit.object) : null)
  }

  private setHovered(equipment: Object3D | null) {
    if (equipment === this.hovered) return
    for (const [mesh, material] of this.highlighted) {
      ;(mesh.material as Material).dispose()
      mesh.material = material
    }
    this.highlighted.clear()
    this.hovered = equipment
    this.renderer.domElement.style.cursor = equipment ? 'pointer' : ''
    if (!equipment) {
      this.onHover(null)
      return
    }
    equipment.traverse((object) => {
      const mesh = object as Mesh
      if (!mesh.isMesh) return
      const original = mesh.material as MeshStandardMaterial
      // Materials are shared between equipment, highlight a copy.
      const material = original.clone()
      material.emissive = original.color.clone()
      material.emissiveIntensity = HIGHLIGHT_INTENSITY
      this.highlighted.set(mesh, original)
      mesh.material = material
    })
    this.onHover({
      name: originalName(this.gltf, equipment),
      category: equipment.userData.category,
      type: equipment.userData.type,
      rack: equipment.userData.rack
    })
  }
}

export async function createViewer(
  container: HTMLElement,
  data: ArrayBuffer,
  onHover: (equipment: HoveredEquipment | null) => void,
  onModeChange?: (mode: CameraMode) => void
): Promise<InfrastructureViewer> {
  return new InfrastructureViewer(container, await parseGlb(data), onHover, onModeChange)
}
